CREATE TABLE "user_profiles" ("id" TEXT NOT NULL, "email" TEXT NULL, "gender" TEXT NOT NULL, "age" INTEGER NOT NULL CHECK (age >= 0), "weight" REAL NOT NULL CHECK (weight >= 0), "height" REAL NOT NULL CHECK (height >= 0), "activity_level" REAL NOT NULL, "target" TEXT NOT NULL, "daily_calories" REAL NOT NULL, "daily_protein" REAL NOT NULL, "daily_carbs" REAL NOT NULL, "daily_fat" REAL NOT NULL, "preferences" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "workout_sessions" ("id" TEXT NOT NULL, "date" INTEGER NOT NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "workout_sets" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL, "exercise_id" TEXT NOT NULL, "set_number" INTEGER NOT NULL CHECK (set_number >= 0), "weight" REAL NOT NULL CHECK (weight >= 0), "reps" INTEGER NOT NULL CHECK (reps >= 0), "rpe" INTEGER NULL, "calculated1rm" REAL NULL, "weight_type" TEXT NULL, "distance" REAL NULL, "duration_seconds" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "user_meals" ("id" TEXT NOT NULL, "date" INTEGER NOT NULL, "meal_type" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "meal_items" ("id" TEXT NOT NULL, "meal_id" TEXT NOT NULL, "food_id" TEXT NOT NULL, "amount" REAL NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "exercises" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "target_muscle" TEXT NOT NULL, "equipment" TEXT NOT NULL, "description" TEXT NULL, "video_url" TEXT NULL, "is_custom" INTEGER NOT NULL DEFAULT 0 CHECK ("is_custom" IN (0, 1)), "tracking_type" TEXT NULL, "secondary_tracking_types" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "foods" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "calories" REAL NOT NULL, "protein" REAL NOT NULL, "carbs" REAL NOT NULL, "fat" REAL NOT NULL, "fiber" REAL NOT NULL DEFAULT 0.0, "sugar" REAL NOT NULL DEFAULT 0.0, "saturated_fat" REAL NOT NULL DEFAULT 0.0, "sodium" REAL NOT NULL DEFAULT 0.0, "category" TEXT NULL, "is_custom" INTEGER NOT NULL DEFAULT 0 CHECK ("is_custom" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "routines" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "routine_exercises" ("id" TEXT NOT NULL, "routine_id" TEXT NOT NULL, "exercise_id" TEXT NOT NULL, "order_index" INTEGER NOT NULL, PRIMARY KEY ("id"));